import json
def build(n, seed):
    g=[[0]*n for _ in range(n)]
    # 2s: V arms from seed, rows 0..min(n-1, seed)
    for i in range(min(n-1, seed)+1):
        for j in (seed-i, seed+i):
            if 0<=j<n: g[i][j]=2
    # 1s: rays from left-arm cells i>=2, down-right
    for i0 in range(2, n):
        j0 = seed-i0
        if j0<0 or j0>=n: continue
        tmax = (n-1-i0) if i0>=seed else seed-i0
        for t in range(1, tmax+1):
            r,c=i0+t, j0+t
            if r<n and c<n: g[r][c]=1
    return g

